   269  // Append "str" at "out_cur".  If there is an overflow, "overflowed"
   270  // is set to true for later use.  The output string is ensured to
   271  // always terminate with '\0' as long as there is no overflow.
   272  static void Append(State *state, const char * const str, ssize_t length) {
   273    for (ssize_t i = 0; i < length; ++i) {
   274      if (state->out_cur + 1 < state->out_end) {  // +1 for '\0'
   275        *state->out_cur = str[i];
   276        ++state->out_cur;
   277      } else {
   278        state->overflowed = true;
   279        break;
   280      }
   281    }
   282    if (!state->overflowed) {
   283      *state->out_cur = '\0';  // Terminate it with '\0'
   284    }
   285  }
